import re

from schedule_parser.conditions import (
    build_fault_condition,
    build_fault_conditions,
    build_file_syscall,
    build_syscall,
    build_time,
    build_user_function,
    fault_dependency_condition,
    file_syscall_condition,
    get_cond_type_nr,
)


def _c_string_escape(value):
    # Escapes a Python string for safe embedding inside a C double-quoted
    # string literal generated by build_fault_details(). Backslash must be
    # escaped first, then double quotes - reversing the order would
    # double-escape the quotes' own backslash.
    return value.replace("\\", "\\\\").replace('"', '\\"')


class Fault:
    name = ""
    type = ""
    fault_category = 0
    fault_specifics = None
    target = ""
    target_nr = 0
    traced = ""
    traced_nr = 0
    repeatable = 0
    duration = 0
    occurrences = 1
    begin_conditions = []
    end_conditions = []
    trigger_statement_begin = ""
    trigger_statement_end = ""
    exit = 0
    start_time = 0
    state_score = 0.0
    event_id = 0

    def to_yaml(self):
        fault = {}
        fault["type"] = self.type
        fault["target"] = self.target
        fault["traced"] = self.traced
        fault["duration"] = self.duration
        fault["begin_conditions"] = []
        if self.occurrences > 0:
            fault["occurrences"] = self.occurrences
        cond_count = 0
        for condition in self.begin_conditions:
            condition_nr = "condition_nr" + str(cond_count)
            fault["begin_conditions"].append({condition_nr: condition.to_yaml()})
            cond_count += 1

        if self.type == "block_ips":
            fault["ips_in"] = []
            fault["ips_out"] = []

            for ip in self.fault_specifics.nodes_in:
                fault["ips_in"].append(ip)
            for ip in self.fault_specifics.nodes_out:
                fault["ips_out"].append(ip)

        if self.type == "syscall":
            fault["details"] = {}
            fault["details"]["name"] = self.fault_specifics.syscall_name
            fault["details"]["return_value"] = int(self.fault_specifics.return_value)
            fault["details"]["repeatable"] = self.repeatable

        if self.type == "partial_write":
            fault["details"] = {
                "count": int(self.fault_specifics.count),
                "corrupt_buffer": int(self.fault_specifics.corrupt_buffer),
            }

        if self.type == "partial_read":
            fault["details"] = {"count": int(self.fault_specifics.count)}

        if self.type == "torn_read":
            fault["details"] = {"offset": int(self.fault_specifics.offset)}
        return fault

    def __repr__(self):
        if self.type == "syscall":
            details = self.fault_specifics.syscall_name
            details = details + " " + str(self.fault_specifics.return_value)

            if len(self.begin_conditions) > 0:
                if self.begin_conditions[0] is file_syscall_condition:
                    details = details + " " + self.begin_conditions[0].file_name
        else:
            details = self.type
        return f"Fault (name={self.name}, state_score = {self.state_score}, type={self.type},details={details},target={self.target},traced={self.traced},start_time={self.start_time},duration={self.duration},event={self.event_id})\n"


# Type of faults
class syscall:
    syscall_name = ""
    success = 0
    return_value = 0


class block_ips:
    nodes_in = []
    nodes_out = []


class process_fault:
    type = 0


class lazyfs_fault:
    type = 0
    operation = ""
    file = ""
    op = ""
    persist = ""
    parts = ""
    parts_bytes = ""
    from_rgx = ""
    to_rgx = ""


class partial_write_fault:
    count = 0
    # 0 (default): genuine short write only, buffer untouched - a correct
    # retry fully recovers. 1: also poisons the userspace buffer's tail, so
    # even a correct retry persists garbage.
    corrupt_buffer = 0


class partial_read_fault:
    # Bytes to truncate the target's next read() to - buffer beyond that is
    # left untouched, a genuine short read.
    count = 0


class torn_read_fault:
    # Offset within the *actually returned* bytes to start poisoning with
    # 0xEE from - read() still reports its real, full success count.
    offset = 0


def parse_faults(faults, nodes):
    faults_dict = {}
    for key, value in faults.items():
        faults_dict[key] = createFault(key, value, nodes)
    return faults_dict


def createFault(name, faultconfig, nodes_dict):
    fault = Fault()
    # print(faultconfig)
    fault.name = name

    fault.type = faultconfig["type"]

    if fault.type == "block_ips":
        fault.fault_category = 0
        block_ips_fault = block_ips()

        nodes_in = []
        nodes_out = []
        if "ips_in" in faultconfig:
            for node in faultconfig["ips_in"]:
                nodes_in.append(node)
        if "ips_out" in faultconfig:
            for node in faultconfig["ips_out"]:
                nodes_out.append(node)

        block_ips_fault.nodes_in = nodes_in
        block_ips_fault.nodes_out = nodes_out

        fault.fault_specifics = block_ips_fault
    if fault.type == "drop_packets":
        fault.fault_category = 0

    if fault.type == "syscall":
        fault.fault_category = 2
        syscall_fault = syscall()
        syscall_fault.syscall_name = faultconfig["details"]["name"]
        syscall_fault.return_value = faultconfig["details"]["return_value"]

        if "success" in faultconfig["details"]:
            success = faultconfig["details"]["success"]

            if success:
                syscall_fault.success = 1
            else:
                syscall_fault.success = 0

        fault.fault_specifics = syscall_fault

    if fault.type == "process_kill" or fault.type == "process_pause" or fault.type == "process_restart":
        fault.fault_category = 1

    if fault.type == "lazyfs":
        fault.fault_category = 4
        lazyfs = lazyfs_fault()

        if "operation" in faultconfig["details"]:
            lazyfs.operation = faultconfig["details"]["operation"]
        else:
            print("No operation specified for lazyfs fault")
            exit(1)

        details = faultconfig["details"]

        def _as_csv(value):
            # Accept either a YAML list ([3, 4]) or a plain "3,4" string, since
            # LazyFS's pipe protocol wants persist/parts_bytes as a comma-separated list.
            if isinstance(value, list):
                return ",".join(str(v) for v in value)
            return str(value)

        # torn-op/torn-seq params - see rose/lazyfs's `lazyfs::torn-op`/`lazyfs::torn-seq`
        # pipe command syntax. file is a literal path. from_rgx/to_rgx are a
        # regex-based alternative to file, but only for the crash_fs operation
        # (LazyFS's own `crash` fault) - LazyFS's torn-op/torn-seq fifo commands
        # don't accept from_rgx/to_rgx at all and reject the whole fault if sent.
        if "file" in details:
            lazyfs.file = details["file"]
        if "op" in details:
            lazyfs.op = details["op"]
        if "persist" in details:
            lazyfs.persist = _as_csv(details["persist"])
        if "parts" in details:
            lazyfs.parts = str(details["parts"])
        if "parts_bytes" in details:
            lazyfs.parts_bytes = _as_csv(details["parts_bytes"])
        if "from_rgx" in details:
            lazyfs.from_rgx = details["from_rgx"]
        if "to_rgx" in details:
            lazyfs.to_rgx = details["to_rgx"]

        if lazyfs.operation in ("torn_op", "torn_seq") and (lazyfs.from_rgx or lazyfs.to_rgx):
            print(
                f"WARNING: lazyfs fault '{name}' sets from_rgx/to_rgx on operation "
                f"'{lazyfs.operation}', which LazyFS's torn-op/torn-seq pipe commands do "
                "not support (crash_fs-only) - LazyFS will reject this fault entirely."
            )

        fault.fault_specifics = lazyfs

    if fault.type == "partial_write":
        fault.fault_category = 5
        pwf = partial_write_fault()
        pwf.count = faultconfig["details"]["count"]
        if "corrupt_buffer" in faultconfig["details"]:
            pwf.corrupt_buffer = 1 if faultconfig["details"]["corrupt_buffer"] else 0
        fault.fault_specifics = pwf

    if fault.type == "partial_read":
        fault.fault_category = 5
        prf = partial_read_fault()
        prf.count = faultconfig["details"]["count"]
        fault.fault_specifics = prf

    if fault.type == "torn_read":
        fault.fault_category = 5
        trf = torn_read_fault()
        trf.offset = faultconfig["details"]["offset"]
        fault.fault_specifics = trf

    if "target" in faultconfig:
        fault.target = faultconfig["target"]
        for name, node in nodes_dict.items():
            if name == fault.target:
                fault.target_nr = node.node_nr

        if fault.target == "primary":
            fault.target_nr = -1
        if fault.target == "majority":
            fault.target_nr = -2
        # "any": first of this fault's N begin_conditions to match wins -
        # e.g. N user_function conditions, one per node, whichever node
        # calls the traced function first gets the fault. Unlike majority
        # (AND: every condition must match before injecting on several
        # nodes), this is OR, gated by a real kernel-side CAS
        # (state_processor.bpf.h, fault->claimed) so exactly one node ever
        # gets injected even if two conditions are satisfied together.
        if fault.target == "any":
            fault.target_nr = -3

    if "traced" in faultconfig:
        fault.traced = faultconfig["traced"]
        for name, node in nodes_dict.items():
            if name == fault.traced:
                fault.traced_nr = node.node_nr
    else:
        fault.traced = fault.target
        fault.traced_nr = fault.target_nr

    if "repeatable" in faultconfig:
        repeatable = faultconfig["repeatable"]
        # print(repeatable)
        if repeatable:
            fault.repeatable = 1

    if "duration" in faultconfig:
        fault.duration = faultconfig["duration"]

    if "occurrences" in faultconfig:
        # print(faultconfig['occurrences'])
        fault.occurrences = faultconfig["occurrences"]

    if "exit" in faultconfig:
        fault.exit = 1 if faultconfig["exit"] else 0

    # fault.trigger_statement_begin = faultconfig['begin_conditions']['trigger_statement']

    begin_conditions = faultconfig["begin_conditions"]

    fault.begin_conditions = []

    conditions_count = 0
    for condition in begin_conditions:
        condition = next(iter(condition.values()))
        type_cond = condition["type"]
        if type_cond == "trigger_statement":
            continue

        if type_cond == "user_function":
            condition = build_user_function(condition)
            cond_nr = get_cond_type_nr(1, condition)
            # condition.cond_nr = cond_nr
            fault.begin_conditions.append(condition)

        if type_cond == "file_syscall":
            condition = build_file_syscall(condition)
            cond_nr = get_cond_type_nr(2, condition)
            condition.cond_nr = cond_nr
            fault.begin_conditions.append(condition)

        if type_cond == "syscall":
            condition = build_syscall(condition)
            cond_nr = get_cond_type_nr(3, condition)
            condition.cond_nr = cond_nr
            fault.begin_conditions.append(condition)

        if type_cond == "time":
            condition = build_time(condition)
            fault.begin_conditions.append(condition)

        if type_cond == "fault_condition":
            condition = build_fault_condition(condition)
            fault.begin_conditions.append(condition)

    # A syscall-override fault (type "syscall") whose only trigger is a
    # user_function (file:line / uprobe) condition would arm in the uprobe
    # handler - which has no syscall pt_regs, so it cannot bpf_override_return and
    # can only mark itself "armed". The target syscall's kprobe then has to route
    # into the fault check to actually fire it, and that only happens when that
    # syscall is registered as a condition. Synthesize that condition on the
    # fault's own syscall, so a standalone syscall_error / disk_failure at a
    # file:line fires (on the first such syscall after the uprobe) with no extra
    # per-syscall cost on any other syscall.
    _cond_names = [type(c).__name__ for c in fault.begin_conditions]
    if (
        fault.type == "syscall"
        and "user_function_condition" in _cond_names
        and not any(
            n in _cond_names
            for n in ("syscall_condition", "file_syscall_condition", "time_cond", "fault_dependency_condition")
        )
    ):
        _sc_name = getattr(fault.fault_specifics, "syscall_name", "")
        if _sc_name:
            _synth = build_syscall({"syscall_name": _sc_name, "call_count": 1})
            _synth_nr = get_cond_type_nr(3, _synth)
            if _synth_nr is not None:
                _synth.cond_nr = _synth_nr
                fault.begin_conditions.append(_synth)

    if "end_conditions" in faultconfig:
        fault.trigger_statement_end = faultconfig["end_conditions"]["trigger_statement"]

        end_conditions = faultconfig["end_conditions"]

        conditions_count = 0
        for name, value in end_conditions.items():
            # todo
            continue

    return fault


def build_faults_cfile(file, nodes, faults, reserved_slots=0):
    build_faults_begin = """\nfault* build_faults_extra(){\n"""
    file.write(build_faults_begin)

    build_faults_malloc = """    fault* faults = ( fault*)malloc(FAULT_COUNT * sizeof(fault));\n"""
    file.write(build_faults_malloc)

    if faults is None:
        faults = {}

    fault_name_to_nr = {name: i for i, name in enumerate(faults.keys())}
    for fault in faults.values():
        for cond in fault.begin_conditions:
            if isinstance(cond, fault_dependency_condition):
                if cond.name not in fault_name_to_nr:
                    print(f"ERROR: fault_condition references unknown fault '{cond.name}'")
                    exit(1)
                cond.fault_nr = fault_name_to_nr[cond.name]

    fault_count = 0
    for name, fault in faults.items():
        create_fault_detail_var = """    fault_details fault_details#fault_nr;\n"""
        create_fault_detail_var = create_fault_detail_var.replace("#fault_nr", str(fault_count))
        file.write(create_fault_detail_var)

        fault_type_nr = get_fault_type_nr(fault.type, fault.fault_specifics)

        fault_details = None

        fault_details = build_fault_details(fault.type, fault_type_nr, fault_count, fault.fault_specifics, nodes, "")

        file.write(fault_details)
        build_fault = """    create_fault(&faults[#faultnr],"#name",#target,#traced,#fault_type,#fault_category,fault_details#fault_nr,#repeat,#occurrences,#duration,#condition_count,#exit);\n\n"""

        build_fault = build_fault.replace("#faultnr", str(fault_count))
        build_fault = build_fault.replace("#name", fault.name)
        build_fault = build_fault.replace("#target", str(fault.target_nr))
        build_fault = build_fault.replace("#traced", str(fault.traced_nr))

        build_fault = build_fault.replace("#fault_type", str(fault_type_nr))

        build_fault = build_fault.replace("#fault_category", str(fault.fault_category))
        build_fault = build_fault.replace("#fault_nr", str(fault_count))
        build_fault = build_fault.replace("#repeat", str(fault.repeatable))
        build_fault = build_fault.replace("#occurrences", str(fault.occurrences))
        build_fault = build_fault.replace("#duration", str(fault.duration))
        build_fault = build_fault.replace("#condition_count", str(len(fault.begin_conditions)))
        build_fault = build_fault.replace("#exit", str(fault.exit))
        # build_fault = build_fault.replace("#faultnr",str(fault_count))
        # build_fault = build_fault.replace("#faultnr",str(fault_count))
        file.write(build_fault)

        build_fault_conditions(file, fault_count, fault.begin_conditions)

        fault_count += 1

    # Reserved slots for toexfi/rose_injector.py's RoseInjector to
    # arm live, directly in the pinned BPF maps, while this schedule is
    # already running (execution_plan.dynamic.reserved_slots). Each is
    # created with occurrences=0, which state_processor.bpf.h's process()
    # checks (`fault->done >= fault->occurrences`) before ever looking at
    # its conditions - 0 >= 0 is true immediately, so a reserved slot is
    # guaranteed inert from the first event onward until RoseInjector
    # overwrites its BPF map entry with a real fault. type "drop_packets"
    # is just a safe, no-op fault_details (build_fault_details() emits no
    # statements for it) - it never fires because occurrences=0 already
    # rules it out regardless of type.
    for _ in range(reserved_slots):
        create_fault_detail_var = """    fault_details fault_details#fault_nr;\n"""
        create_fault_detail_var = create_fault_detail_var.replace("#fault_nr", str(fault_count))
        file.write(create_fault_detail_var)

        fault_details = build_fault_details("drop_packets", get_fault_type_nr("drop_packets", None), fault_count, None, nodes, "")
        file.write(fault_details)

        build_fault = """    create_fault(&faults[#faultnr],"#name",0,0,#fault_type,0,fault_details#fault_nr,0,0,0,0,0);\n\n"""
        build_fault = build_fault.replace("#faultnr", str(fault_count))
        build_fault = build_fault.replace("#name", f"__dynamic_slot_{fault_count}")
        build_fault = build_fault.replace("#fault_type", str(get_fault_type_nr("drop_packets", None)))
        build_fault = build_fault.replace("#fault_nr", str(fault_count))
        file.write(build_fault)

        fault_count += 1

    build_faults_end = """
    return faults;
}"""
    file.write(build_faults_end)


def build_fault_details(fault_type, fault_type_nr, fault_nr, fault_specifics, nodes, node_name):
    match fault_type:
        case "block_ips":
            block_ips_definition = """    block_ips block_ips#nr;\n"""
            block_ips_definition = block_ips_definition.replace("#nr", str(fault_nr))
            ip_count_in = 0
            ip_count_out = 0

            for name in fault_specifics.nodes_in:
                add_ip_block_line = """    add_ip_to_block_extra(&block_ips#nr,"#ipname",#ipnr,#direction);\n"""

                ip = nodes[name].ip
                add_ip_block_line = add_ip_block_line.replace("#nr", str(fault_nr))
                add_ip_block_line = add_ip_block_line.replace("#ipname", str(ip))
                add_ip_block_line = add_ip_block_line.replace("#ipnr", str(ip_count_in))
                add_ip_block_line = add_ip_block_line.replace("#direction", str(1))
                block_ips_definition = block_ips_definition + add_ip_block_line
                ip_count_in += 1

            for name in fault_specifics.nodes_out:
                add_ip_block_line = """    add_ip_to_block_extra(&block_ips#nr,"#ipname",#ipnr,#direction);\n"""

                ip = nodes[name].ip
                add_ip_block_line = add_ip_block_line.replace("#nr", str(fault_nr))
                add_ip_block_line = add_ip_block_line.replace("#ipname", str(ip))
                add_ip_block_line = add_ip_block_line.replace("#ipnr", str(ip_count_out))
                add_ip_block_line = add_ip_block_line.replace("#direction", str(2))
                block_ips_definition = block_ips_definition + add_ip_block_line
                ip_count_out += 1

            assign_line = """    fault_details#nr.block_ips = block_ips#nr;\n"""
            assign_line += """    fault_details#nr.block_ips.count_in = #ip_count_in;\n"""
            assign_line += """    fault_details#nr.block_ips.count_out = #ip_count_out;\n"""

            assign_line = assign_line.replace("#ip_count_in", str(ip_count_in))
            assign_line = assign_line.replace("#ip_count_out", str(ip_count_out))

            assign_line = assign_line.replace("#nr", str(fault_nr))

            block_ips_definition += assign_line
            return block_ips_definition

        case "drop_packets":
            return ""

        case "process_kill":
            process_kill_definition = """    process_fault process_kill#nr;\n"""
            process_kill_definition = process_kill_definition.replace("#nr", str(fault_nr))

            process_kill_definition += """    process_kill#nr.type = #fault_type_nr;\n"""
            process_kill_definition = process_kill_definition.replace("#fault_type_nr", str(fault_type_nr))
            process_kill_definition += """    fault_details#nr.process_fault = process_kill#nr;\n"""
            process_kill_definition = process_kill_definition.replace("#nr", str(fault_nr))
            return process_kill_definition
        case "process_pause":
            process_pause_definition = """    process_fault process_pause#nr;\n"""
            process_pause_definition = process_pause_definition.replace("#nr", str(fault_nr))

            process_pause_definition += """    process_pause#nr.type = #fault_type_nr;\n"""
            process_pause_definition = process_pause_definition.replace("#fault_type_nr", str(fault_type_nr))
            process_pause_definition += """    fault_details#nr.process_fault = process_pause#nr;\n"""
            process_pause_definition = process_pause_definition.replace("#nr", str(fault_nr))
            return process_pause_definition
        case "process_restart":
            process_restart_definition = """   process_fault process_restart#nr;\n"""
            process_restart_definition = process_restart_definition.replace("#nr", str(fault_nr))

            process_restart_definition += """  process_restart#nr.type = #fault_type_nr;\n"""
            process_restart_definition = process_restart_definition.replace("#fault_type_nr", str(fault_type_nr))
            process_restart_definition += """  fault_details#nr.process_fault = process_restart#nr;\n"""
            process_restart_definition = process_restart_definition.replace("#nr", str(fault_nr))
            return process_restart_definition

        case "syscall":
            syscall_definition = """    syscall_operation syscall#nr;\n"""
            syscall_definition += """    syscall#nr.syscall = #fault_type_nr;\n"""
            syscall_definition = syscall_definition.replace("#fault_type_nr", str(fault_type_nr))
            syscall_definition += """    syscall#nr.success = #success;\n"""
            syscall_definition = syscall_definition.replace("#success", str(fault_specifics.success))
            syscall_definition += """    syscall#nr.return_value = #return_value;\n"""
            syscall_definition = syscall_definition.replace("#return_value", str(fault_specifics.return_value))
            syscall_definition += """    fault_details#nr.syscall = syscall#nr;\n"""
            syscall_definition = syscall_definition.replace("#nr", str(fault_nr))
            return syscall_definition

        case "lazyfs":
            lazyfs_fault = """    lazyfs_fault lazyfs_fault#nr;\n"""
            lazyfs_fault += """    lazyfs_fault#nr.operation = #fault_type_nr;\n"""
            lazyfs_fault += """    strcpy(lazyfs_fault#nr.file, "#file");\n"""
            lazyfs_fault += """    strcpy(lazyfs_fault#nr.fs_op, "#fs_op");\n"""
            lazyfs_fault += """    strcpy(lazyfs_fault#nr.persist, "#persist");\n"""
            lazyfs_fault += """    strcpy(lazyfs_fault#nr.parts_bytes, "#parts_bytes");\n"""
            lazyfs_fault += """    strcpy(lazyfs_fault#nr.parts, "#parts");\n"""
            lazyfs_fault += """    strcpy(lazyfs_fault#nr.from_rgx, "#from_rgx");\n"""
            lazyfs_fault += """    strcpy(lazyfs_fault#nr.to_rgx, "#to_rgx");\n"""
            lazyfs_fault += """    fault_details#nr.lazyfs_fault = lazyfs_fault#nr;\n"""
            lazyfs_fault = lazyfs_fault.replace("#fault_type_nr", str(fault_type_nr))
            lazyfs_fault = lazyfs_fault.replace("#file", _c_string_escape(fault_specifics.file))
            lazyfs_fault = lazyfs_fault.replace("#fs_op", _c_string_escape(fault_specifics.op))
            lazyfs_fault = lazyfs_fault.replace("#persist", _c_string_escape(fault_specifics.persist))
            # #parts_bytes before #parts - #parts is a prefix of #parts_bytes.
            lazyfs_fault = lazyfs_fault.replace("#parts_bytes", _c_string_escape(fault_specifics.parts_bytes))
            lazyfs_fault = lazyfs_fault.replace("#parts", _c_string_escape(fault_specifics.parts))
            lazyfs_fault = lazyfs_fault.replace("#from_rgx", _c_string_escape(fault_specifics.from_rgx))
            lazyfs_fault = lazyfs_fault.replace("#to_rgx", _c_string_escape(fault_specifics.to_rgx))
            lazyfs_fault = lazyfs_fault.replace("#nr", str(fault_nr))
            return lazyfs_fault

        case "partial_write":
            partial_write_definition = """    partial_write_fault partial_write_fault#nr;\n"""
            partial_write_definition += """    partial_write_fault#nr.count = #count;\n"""
            partial_write_definition += """    partial_write_fault#nr.corrupt_buffer = #corrupt_buffer;\n"""
            partial_write_definition += """    fault_details#nr.partial_write_fault = partial_write_fault#nr;\n"""
            partial_write_definition = partial_write_definition.replace("#count", str(fault_specifics.count))
            partial_write_definition = partial_write_definition.replace("#corrupt_buffer", str(fault_specifics.corrupt_buffer))
            partial_write_definition = partial_write_definition.replace("#nr", str(fault_nr))
            return partial_write_definition

        case "partial_read":
            partial_read_definition = """    partial_read_fault partial_read_fault#nr;\n"""
            partial_read_definition += """    partial_read_fault#nr.count = #count;\n"""
            partial_read_definition += """    fault_details#nr.partial_read_fault = partial_read_fault#nr;\n"""
            partial_read_definition = partial_read_definition.replace("#count", str(fault_specifics.count))
            partial_read_definition = partial_read_definition.replace("#nr", str(fault_nr))
            return partial_read_definition

        case "torn_read":
            torn_read_definition = """    torn_read_fault torn_read_fault#nr;\n"""
            torn_read_definition += """    torn_read_fault#nr.offset = #offset;\n"""
            torn_read_definition += """    fault_details#nr.torn_read_fault = torn_read_fault#nr;\n"""
            torn_read_definition = torn_read_definition.replace("#offset", str(fault_specifics.offset))
            torn_read_definition = torn_read_definition.replace("#nr", str(fault_nr))
            return torn_read_definition


def get_fault_type_nr(type, fault_specifics):
    match type:
        case "network_isolation":
            return 4
        case "block_ips":
            return 5
        case "drop_packets":
            return 6
        case "process_kill":
            return 11
        case "process_pause":
            return 14
        case "process_restart":
            return 22
        case "partial_write":
            return "PARTIAL_WRITE_FAULT"
        case "partial_read":
            return "PARTIAL_READ_FAULT"
        case "torn_read":
            return "TORN_READ_FAULT"
        case "syscall":
            if fault_specifics.success == 0:
                match fault_specifics.syscall_name:
                    # Needs success = 0
                    case "write":
                        return 2
                    case "read":
                        return 3
                    case "open":
                        return 15
                    case "mkdir":
                        return 23
                    case "newfstatat":
                        return "NEWFSTATAT_FAULT"
                    case "openat":
                        return "OPENAT_FAULT"
                    case "fdatasync":
                        return "FDATASYNC_FAULT"
                    case "pwrite64":
                        return "PWRITE64_FAULT"
                    case "accept":
                        return "ACCEPT_FAULT"
                    case "close":
                        return "CLOSE_FAULT"
                    case "futex":
                        return "FUTEX_FAULT"
                    case "connect":
                        return "CONNECT_FAULT"
                    case "fsync":
                        return "FSYNC_FAULT"
                    case "stat":
                        return "STAT_FAULT"
                    case "lstat":
                        return "LSTAT_FAULT"
                    case "rename":
                        return "RENAME_FAULT"
                    case "unlink":
                        return "UNLINK_FAULT"
                    case "sync_file_range":
                        return "SYNC_FILE_RANGE_FAULT"
                    case "bind":
                        return "BIND_FAULT"
                    case "clone":
                        return "CLONE_FAULT"
                    case "dup":
                        return "DUP_FAULT"
                    case "mmap":
                        return "MMAP_FAULT"
                    case "epoll_create1":
                        return "EPOLL_CREATE1_FAULT"
                    case "epoll_ctl":
                        return "EPOLL_CTL_FAULT"
                    case "epoll_pwait":
                        return "EPOLL_PWAIT_FAULT"
                    case "eventfd2":
                        return "EVENTFD2_FAULT"
                    case "fcntl":
                        return "FCNTL_FAULT"
                    case "flock":
                        return "FLOCK_FAULT"
                    case "fstat":
                        return "FSTAT_FAULT"
                    case "ftruncate":
                        return "FTRUNCATE_FAULT"
                    case "getdents64":
                        return "GETDENTS64_FAULT"
                    case "getpeername":
                        return "GETPEERNAME_FAULT"
                    case "getsockname":
                        return "GETSOCKNAME_FAULT"
                    case "ioctl":
                        return "IOCTL_FAULT"
                    case "listen":
                        return "LISTEN_FAULT"
                    case "madvise":
                        return "MADVISE_FAULT"
                    case "mkdirat":
                        return "MKDIRAT_FAULT"
                    case "mprotect":
                        return "MPROTECT_FAULT"
                    case "pipe":
                        return "PIPE_FAULT"
                    case "prctl":
                        return "PRCTL_FAULT"
                    case "sched_getaffinity":
                        return "SCHED_GETAFFINITY_FAULT"
                    case "socket":
                        return "SOCKET_FAULT"
                    case "statfs":
                        return "STATFS_FAULT"
                    case "tgkill":
                        return "TGKILL_FAULT"
                    case "unlinkat":
                        return "UNLINKAT_FAULT"
                    case "msync":
                        return "MSYNC_FAULT"
                    case "renameat":
                        return "RENAMEAT_FAULT"
                    case "execve":
                        return "EXECVE_FAULT"
                    case "accept4":
                        return "ACCEPT4_FAULT"
                    case _:
                        return "TEMP_EMPTY"
            if fault_specifics.success == 1:
                match fault_specifics.syscall_name:
                    case "fdatasync":
                        return "FDATASYNC_RET_FAULT"
        case "lazyfs":
            if fault_specifics.operation == "torn_seq":
                return "TORN_SEQ"
            if fault_specifics.operation == "torn_op":
                return "TORN_OP"
            if fault_specifics.operation == "clear_cache":
                return "CLEAR_CACHE"
            if fault_specifics.operation == "crash_fs":
                return "CRASH_FS"


